from typing import Optional, Dict, Any, List, Union, TypeVar, Callable, Type, cast
from enum import Enum
from datetime import datetime
import dateutil.parser


T = TypeVar("T")
EnumT = TypeVar("EnumT", bound=Enum)


def from_str(x: Any) -> str:
    assert isinstance(x, str)
    return x


def from_none(x: Any) -> Any:
    assert x is None
    return x


def from_union(fs, x):
    for f in fs:
        try:
            return f(x)
        except:
            pass
    assert False


def from_dict(f: Callable[[Any], T], x: Any) -> Dict[str, T]:
    assert isinstance(x, dict)
    return { k: f(v) for (k, v) in x.items() }


def from_list(f: Callable[[Any], T], x: Any) -> List[T]:
    assert isinstance(x, list)
    return [f(y) for y in x]


def to_class(c: Type[T], x: Any) -> dict:
    assert isinstance(x, c)
    return cast(Any, x).to_dict()


def from_float(x: Any) -> float:
    assert isinstance(x, (float, int)) and not isinstance(x, bool)
    return float(x)


def to_float(x: Any) -> float:
    assert isinstance(x, (int, float))
    return x


def to_enum(c: Type[EnumT], x: Any) -> EnumT:
    assert isinstance(x, c)
    return x.value


def from_int(x: Any) -> int:
    assert isinstance(x, int) and not isinstance(x, bool)
    return x


def from_bool(x: Any) -> bool:
    assert isinstance(x, bool)
    return x


def from_datetime(x: Any) -> datetime:
    return dateutil.parser.parse(x)


class GraphqlRequest:
    operation_name: Optional[str]
    """The name of the operation to execute"""

    query: str
    """The GraphQL query or mutation string"""

    variables: Optional[Dict[str, Any]]
    """The variables for the GraphQL operation"""

    def __init__(self, operation_name: Optional[str], query: str, variables: Optional[Dict[str, Any]]) -> None:
        self.operation_name = operation_name
        self.query = query
        self.variables = variables

    @staticmethod
    def from_dict(obj: Any) -> 'GraphqlRequest':
        assert isinstance(obj, dict)
        operation_name = from_union([from_str, from_none], obj.get("operationName"))
        query = from_str(obj.get("query"))
        variables = from_union([lambda x: from_dict(lambda x: x, x), from_none], obj.get("variables"))
        return GraphqlRequest(operation_name, query, variables)

    def to_dict(self) -> dict:
        result: dict = {}
        if self.operation_name is not None:
            result["operationName"] = from_union([from_str, from_none], self.operation_name)
        result["query"] = from_str(self.query)
        if self.variables is not None:
            result["variables"] = from_union([lambda x: from_dict(lambda x: x, x), from_none], self.variables)
        return result


class Error:
    message: Optional[str]

    def __init__(self, message: Optional[str]) -> None:
        self.message = message

    @staticmethod
    def from_dict(obj: Any) -> 'Error':
        assert isinstance(obj, dict)
        message = from_union([from_str, from_none], obj.get("message"))
        return Error(message)

    def to_dict(self) -> dict:
        result: dict = {}
        if self.message is not None:
            result["message"] = from_union([from_str, from_none], self.message)
        return result


class GraphqlResponse:
    data: Optional[Dict[str, Any]]
    """The data returned by the GraphQL operation"""

    errors: Optional[List[Error]]
    """Any errors returned by the GraphQL operation"""

    def __init__(self, data: Optional[Dict[str, Any]], errors: Optional[List[Error]]) -> None:
        self.data = data
        self.errors = errors

    @staticmethod
    def from_dict(obj: Any) -> 'GraphqlResponse':
        assert isinstance(obj, dict)
        data = from_union([lambda x: from_dict(lambda x: x, x), from_none], obj.get("data"))
        errors = from_union([lambda x: from_list(Error.from_dict, x), from_none], obj.get("errors"))
        return GraphqlResponse(data, errors)

    def to_dict(self) -> dict:
        result: dict = {}
        if self.data is not None:
            result["data"] = from_union([lambda x: from_dict(lambda x: x, x), from_none], self.data)
        if self.errors is not None:
            result["errors"] = from_union([lambda x: from_list(lambda x: to_class(Error, x), x), from_none], self.errors)
        return result


